import openpyxl,json,datetime,pathlib
root=pathlib.Path('/workspace/mu')
p='/workspace/attachments/ab1f3992-f149-4029-a6af-afb47951cb55/美容報表.xlsx'
w=openpyxl.load_workbook(p); data=[]
for s in w:
 cells={}
 for row in s:
  for c in row:
   if c.value is not None:
    v=c.value
    if isinstance(v,(datetime.datetime,datetime.date)):v=v.isoformat()[:10]
    elif isinstance(v,datetime.time):v=v.isoformat()
    cells[c.coordinate]={'value':v,'format':c.number_format}
 data.append({'name':s.title,'rows':s.max_row,'cols':s.max_column,'cells':cells,'merges':list(map(str,s.merged_cells.ranges))})
(root/'workbook.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
html='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>美容報表管理</title><style>
*{box-sizing:border-box}body{margin:0;background:#f6efe7;color:#49382d;font-family:system-ui,sans-serif}header{padding:26px 28px;background:#fffaf4;border-bottom:1px solid #dfcdbb}h1{margin:0 0 8px;font-size:26px}p{margin:8px 0;color:#756252}main{padding:20px;max-width:1600px;margin:auto}nav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}button{border:1px solid #d9c4ae;border-radius:8px;padding:10px 14px;background:#fffaf4;color:#574233;cursor:pointer;font:inherit}button.active,button.primary{background:#8a5d3b;color:#fffaf4;border-color:#8a5d3b}.tools{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px}input{padding:10px;border:1px solid #cdb69e;border-radius:6px;font:inherit}.tools input{flex:1;min-width:240px}.panel{background:#fffaf4;padding:18px;border:1px solid #dfcdbb;border-radius:12px}.scroll{overflow:auto;max-height:65vh}table{border-collapse:collapse;font-size:14px;width:100%}td,th{border:1px solid #e2d2c1;min-width:105px;padding:8px;height:36px;white-space:pre-wrap}th{background:#ecdece;position:sticky;top:0;z-index:2;font-weight:500}th:first-child,td.rownum{min-width:42px;width:42px;background:#ecdece;text-align:center}td.formula{background:#f5e8d6;color:#694b31}td.heading{background:#e9d7c3;font-weight:600}td.selected{outline:2px solid #8a5d3b;outline-offset:-2px}#editor{display:none;padding:16px 0}#editor input{width:min(600px,100%)}#status{color:#8a5d3b;min-height:24px}small{color:#786453}.note{background:#f2e2cc;padding:12px;border-radius:8px;margin:14px 0}h2{font-size:20px}footer{padding:20px;color:#756252;font-size:13px}button:hover{background:#f0e1d0}button.active:hover,button.primary:hover{background:#734a2e}button:focus-visible,input:focus-visible,td:focus-visible{outline:2px solid #8a5d3b;outline-offset:2px}input{background:#fffdf9;color:#49382d}.panel{box-shadow:0 4px 18px #49382d08}main{display:grid;grid-template-columns:220px minmax(0,1fr);gap:20px;align-items:start}nav{flex-direction:column;position:sticky;top:20px}nav button{text-align:left}.panel{min-width:0}.financeForm{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:16px 0 24px}.financeForm label{font-size:14px}.financeForm input,.financeForm select{display:block;width:100%;margin-top:6px}.financeForm .wide{grid-column:1/-1}select{padding:10px;border:1px solid #cdb69e;border-radius:6px;background:#fffdf9;color:#49382d;font:inherit}#sharePreview{padding:14px;background:#f5e8d6;border-radius:8px}#financeStatus{color:#8a5d3b}details{margin-top:24px;padding:12px;background:#f6efe7;border-radius:8px}summary{cursor:pointer}[hidden]{display:none!important}@media(max-width:700px){main{display:block;padding:12px}nav{position:static;max-height:180px;overflow:auto;margin-bottom:16px}nav button{padding:10px}.financeForm{grid-template-columns:1fr}.panel{padding:14px}}</style>
<header><h1>美容報表管理</h1><p>依原始 Excel 建立 · 成本、分成、薪資、叫貨與盤點</p></header><main><nav id="tabs"></nav><div class="panel"><h2 id="title"></h2><div class="tools"><input id="search" placeholder="搜尋目前工作表（姓名、產品、日期等）" aria-label="搜尋"><button id="export">匯出資料備份</button><button id="import">匯入資料備份</button><input type="file" id="file" accept=".json" hidden style="display:none"><button id="add">新增一列</button></div><div class="note">淺奶茶色儲存格為公式，自動重新計算。點選任一儲存格即可修改內容。保留原表的人工填寫金額，不擅自推算分成規則；Excel「淨利」欄實際為售價減成本，尚未扣除分潤。</div><div id="editor"><label id="cellLabel" for="value"></label><br><input id="value"><button id="save" class="primary">儲存修改</button><button id="cancel">取消</button><p><small>可輸入文字、數字或原表公式，例如 =E2-D2、=E3*0.1、=SUM(E3:E14)。比例請輸入 0.1 表示 10%。空白會清除此格。</small></p></div><p id="status" role="status"></p><div class="scroll"><table id="table"></table></div><p><small>保留原表合併儲存格。新增列不會自動複製公式或擴展合計範圍，請按需要修改。庫存表為人工進貨／盤點紀錄，尚未與銷售自動連動。</small></p></div></main><footer>資料儲存在此瀏覽器；請定期匯出備份。此檔包含原 Excel 資料，請只提供給有權查看的人員。尚未提供帳號或多人同步。</footer><script>const INITIAL_DATA=__DATA__;</script><script>__MATH__</script><script>__APP__</script></html>'''
html=html.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')).replace('__MATH__',(root/'formulas.js').read_text()).replace('__APP__',(root/'report.js').read_text())
html=html.replace('</html>', '<script>'+(root/'finance.js').read_text()+'</script></html>')
(root/'index.html').write_text(html);(root/'preview.html').write_text(html)
print('Built',len(data),'sheets')
